  "trigger": "使用 PyYAML 5.3 的 yaml.full_load 或 yaml.load(..., Loader=FullLoader) 解析攻击者可控 YAML，且 YAML 含 !!python/object/new 等 Python 对象构造标签。",
  "exploit_evidence": [
    {
      "src": 1,
      "kind": "poc",
      "quote": "# pyyaml==5.3 required. Vulnerability has been fixed in 5.3.1"
    }
  ],
  "fixed_version": "5.3.1",
  "summary_zh": "PyYAML 5.3 的 FullLoader 解析不可信 YAML 可致 RCE，请升级 5.3.1 并避免处理不可信输入。"
}
